	end

	% --- resB modes ---
	j11B = (-2.*epsilon.*(1 + epsilon.^2.*t2).*(q.^2 + epsilon.^2.*r.^2.*T3.*T4))./(q.^2.*RR.^2);
	j11B_FFT = real(fft(j11B, [], 2)) / Ntheta;
	jacTotal(1,1, rowsB, :) = reshape(j11B_FFT(:, mB+1).', [1,1,nmB, Nq]);

	j12B = (-2.*epsilon.*(1 + epsilon.^2.*t2).^2.*(q.^2 + epsilon.^2.*r.^2.*T3.*T4))./(q.^2.*RR.^3);
	j12B_FFT = real(fft(j12B, [], 2)) / Ntheta;
	jacTotal(1,2, rowsB, :) = reshape(j12B_FFT(:, mB+1).', [1,1,nmB, Nq]);

	j13B = (-2.*(epsilon + epsilon.^3.*t2).^2.*(epsilon.^3.*P.*r.^2.*RR.*T3 - q.^2.*cos(omega) + epsilon.*r.^2.*(r.*RR.*T3 - RR.*T4.*T6 - epsilon.^2.*Pp.*RR.*T4.*T6 - epsilon.*T3.*T4.*cos(omega) + deltap.*epsilon.*RR.*T4.*T6.*cos(omega) - epsilon.*RR.*T3.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3) - epsilon.*RR.*T3.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) - epsilon.*RR.*T4.*T6.*cos(omega).*sum(cos((-1 + ms).*omega).*Sp,3) + epsilon.*RR.*T4.*T6.*sin(omega).*sum(sin((-1 + ms).*omega).*Sp,3))))./(q.^2.*RR.^3);
	j13B_FFT = real(fft(j13B, [], 2)) / Ntheta;
	jacTotal(1,3, rowsB, :) = reshape(j13B_FFT(:, mB+1).', [1,1,nmB, Nq]);

	j22B = (-2.*epsilon.^2.*r.^2.*(1 + epsilon.^2.*t2).^2.*T4.*T6.*(epsilon.^2.*P.*cos(omega) + r.*cos(omega) - epsilon.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3)))./(q.^2.*RR.^2);
	j22B_FFT = real(fft(j22B, [], 2)) / Ntheta;
	jacTotal(2,2, rowsB, :) = reshape(j22B_FFT(:, mB+1).', [1,1,nmB, Nq]);

	j23B = (2.*epsilon.^3.*(r + epsilon.^2.*r.*t2).^2.*T4.*T6.*(epsilon.^2.*P + r - epsilon.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3) - epsilon.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3)))./(q.^2.*RR.^2);
	j23B_FFT = real(fft(j23B, [], 2)) / Ntheta;
	jacTotal(2,3, rowsB, :) = reshape(j23B_FFT(:, mB+1).', [1,1,nmB, Nq]);

	% derivatives wrt B_l (bundle)
	for lp = 0:Nb-1
		j13lpB = 2.*BB.*cos(lp.*omega);
		j13lpB_FFT = real(fft(j13lpB, [], 2)) / Ntheta;
		jacTotal(1, 3+lp+1, rowsB, :) = reshape(j13lpB_FFT(:, mB+1).', [1,1,nmB, Nq]);
	end

	% derivatives wrt S_k (bundle), k=2..Ns+1
	for kp = 2:(Ns+1)
        T18 = cos((-1 + kp).*omega).*1.*(epsilon.^2.*P.*cos(omega) + r.*cos(omega) - epsilon.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3)) - 1.*sin((-1 + kp).*omega).*(epsilon.^2.*P.*sin(omega) + r.*sin(omega) - epsilon.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3));
	    T19 = -((-1 + kp).*cos((-1 + kp).*omega).*1.*(-(deltap.*epsilon) + cos(omega) + epsilon.^2.*Pp.*cos(omega) + epsilon.*sum(cos((-1 + ms).*omega).*Sp,3))) - -((-1 + kp).*1.*sin((-1 + kp).*omega)).*(sin(omega) + epsilon.^2.*Pp.*sin(omega) - epsilon.*sum(sin((-1 + ms).*omega).*Sp,3));
        T34 = -2.*((-1 + kp).*cos((-1 + kp).*omega).*1.*(epsilon.^2.*P.*cos(omega) + r.*cos(omega) - epsilon.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3)) + -((-1 + kp).*1.*sin((-1 + kp).*omega)).*(epsilon.^2.*P.*sin(omega) + r.*sin(omega) - epsilon.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3)));

		j13kpB = (epsilon.*(1 + epsilon.^2.*t2).^2.*(epsilon.*r.^2.*RR.*(-(T3.*T34) + 2.*T19.*T4.*T6) + 2.*(q.^2 + epsilon.^2.*r.^2.*T3.*T4).*cos((-1 + kp).*omega).*1))./(q.^2.*RR.^3);
		j13kpB_FFT = real(fft(j13kpB, [], 2)) / Ntheta;
		jacTotal(1, 3 + Nb + (kp - 1), rowsB, :) = reshape(j13kpB_FFT(:, mB+1).', [1,1,nmB, Nq]);
		j23kpB = (2.*epsilon.^2.*r.^2.*T18.*(1 + epsilon.^2.*t2).^2.*T4.*T6)./(q.^2.*RR.^2);
		j23kpB_FFT = real(fft(j23kpB, [], 2)) / Ntheta;
		jacTotal(2, 3 + Nb + (kp - 1), rowsB, :) = reshape(j23kpB_FFT(:, mB+1).', [1,1,nmB, Nq]);
	end
	%% Construct J
    totalDofs = dof_count * (2 + Nb) + (dof_count-1) *(Ns+1);
    nCols = (3+ Nb + Ns)^2 * Nq;
    % precomputed: M_extended (totalDofs x nCols), P_templates{d} with fields i,j,v_template
    J = spalloc(totalDofs, totalDofs, 1 * nnz(M_extended));  % or a tighter nnz estimate

    for d = 1:3
        % Extract jacobian block and flatten in the SAME order P_templates was built.
        jac_d = squeeze(jacTotal(d,:,:,:));    % size: [nProfiles, nProfiles, Nq] (alpha,gamma,q)
        % permute to [q, gamma, alpha] then linearize -> ordering matches P_templates{d}.i
        jacTotal_flat = reshape(permute(jac_d, [3, 1, 2]), [], 1);   % length == nCols

        % Row-scale P template by jac values (this gives diag(jac)*P_extended)
        vP_scaled = P_templates{d}.v_template .* jacTotal_flat(P_templates{d}.i);

        % Create sparse scaled-P and accumulate J via M_extended * P_scaled
        P_scaled = sparse(P_templates{d}.i, P_templates{d}.j, vP_scaled, nCols, totalDofs);
        J = J + M_extended * P_scaled;
    end
end
